# Generated by UniVM BackendPy
# 栈式字节码 -> Python：list 作为操作数栈，dict 作为调用帧。

stack = []
frames = [{}]
FUNCS = {}


class _Return(Exception):
    def __init__(self, value):
        self.value = value


def PUSH(value):
    stack.append(value)


def LOAD(name):
    stack.append(frames[-1].get(name, 0))


def STORE(name):
    frames[-1][name] = stack.pop()


def IADD():
    b = stack.pop()
    a = stack.pop()
    stack.append(a + b)


def ISUB():
    b = stack.pop()
    a = stack.pop()
    stack.append(a - b)


def IMUL():
    b = stack.pop()
    a = stack.pop()
    stack.append(a * b)


def IDIV():
    b = stack.pop()
    a = stack.pop()
    q = abs(a) // abs(b)          # Java long 除法向零截断
    stack.append(-q if (a < 0) != (b < 0) else q)


def INEG():
    stack.append(-stack.pop())


def IEQ():
    b = stack.pop()
    a = stack.pop()
    stack.append(1 if a == b else 0)


def INE():
    b = stack.pop()
    a = stack.pop()
    stack.append(1 if a != b else 0)


def ILT():
    b = stack.pop()
    a = stack.pop()
    stack.append(1 if a < b else 0)


def IGT():
    b = stack.pop()
    a = stack.pop()
    stack.append(1 if a > b else 0)


def ILE():
    b = stack.pop()
    a = stack.pop()
    stack.append(1 if a <= b else 0)


def IGE():
    b = stack.pop()
    a = stack.pop()
    stack.append(1 if a >= b else 0)


def PRINT_INT():
    print(stack.pop())


def POP():
    stack.pop()


def ANEW():
    size = stack.pop()
    stack.append([0] * size)


def AGET():
    idx = stack.pop()
    arr = stack.pop()
    if idx < 0 or idx >= len(arr):
        raise IndexError("数组下标越界: %d" % idx)
    stack.append(arr[idx])


def ASET():
    value = stack.pop()
    idx = stack.pop()
    arr = stack.pop()
    if idx < 0 or idx >= len(arr):
        raise IndexError("数组下标越界: %d" % idx)
    arr[idx] = value


def ALEN():
    stack.append(len(stack.pop()))


def CALL(name, argc):
    args = [stack.pop() for _ in range(argc)][::-1]
    fn, params = FUNCS[name]
    frame = {}
    for param, value in zip(params, args):
        frame[param] = value
    frames.append(frame)
    try:
        fn()
        result = 0
    except _Return as ret:
        result = ret.value
    finally:
        frames.pop()
    stack.append(result)


def RET():
    raise _Return(stack.pop())


def _fn_sum():
    PUSH(0)
    STORE('i')
    PUSH(0)
    STORE('s')
    while True:
        LOAD('i')
        LOAD('arr')
        ALEN()
        ILT()
